"""Alert models: Alert records, delivery status, and persistent deduplication."""
from datetime import datetime, timezone
from sqlalchemy import (
    Column,
    String,
    Text,
    DateTime,
    ForeignKey,
    Index,
    JSON,
    Integer,
    Boolean,
)
from app.database import Base


def utc_now():
    return datetime.now(timezone.utc)


class Alert(Base):
    """Persistent alert / red flag record generated by risk rules or system events."""
    __tablename__ = "alerts"

    id = Column(String(120), primary_key=True)
    dedup_key = Column(String(200), nullable=False, unique=True, index=True)
    account_id = Column(String(100), nullable=True, index=True)
    trader_id = Column(String(100), nullable=True, index=True)
    trade_id = Column(String(120), nullable=True, index=True)
    order_id = Column(String(100), nullable=True, index=True)
    trade_date = Column(String(20), nullable=True, index=True)
    trade_time = Column(String(20), nullable=True)
    rule_name = Column(String(100), nullable=True)
    configured_condition = Column(String(250), nullable=True)
    observed_value = Column(String(250), nullable=True)
    explanation = Column(Text, nullable=True)
    violation_status = Column(String(30), nullable=False, default="ACTIVE")  # ACTIVE, RESOLVED, HISTORICAL, UNEVALUATED
    severity = Column(String(20), nullable=False, default="High")  # High / Medium / Low
    title = Column(String(200), nullable=False)
    message = Column(Text, nullable=False)
    event_time = Column(DateTime(timezone=True), nullable=False, default=utc_now)
    created_at = Column(DateTime(timezone=True), default=utc_now, index=True)


class AlertDeliveryLog(Base):
    """Delivery log tracking attempts to Telegram, WhatsApp, and Email."""
    __tablename__ = "alert_delivery_logs"

    id = Column(String(120), primary_key=True)
    alert_id = Column(String(120), ForeignKey("alerts.id", ondelete="CASCADE"), nullable=False, index=True)
    channel = Column(String(30), nullable=False)  # telegram, whatsapp, email
    recipient = Column(String(200), nullable=False)
    status = Column(String(30), nullable=False, default="PENDING")  # PENDING, SENT, FAILED
    retry_count = Column(Integer, nullable=False, default=0)
    error_message = Column(Text, nullable=True)
    sent_at = Column(DateTime(timezone=True), nullable=True)
    created_at = Column(DateTime(timezone=True), default=utc_now)

    __table_args__ = (
        Index("ix_delivery_channel_status", "channel", "status"),
    )


class SentFlag(Base):
    """Fast deduplication cache for alert checks and expiry notices."""
    __tablename__ = "sent_flags"

    key = Column(String(200), primary_key=True)
    sent_at = Column(DateTime(timezone=True), nullable=False, default=utc_now)
